e .ds-home-note{font-size:.8125rem;line-height:1.8;color:var(--shop-muted,#716157)}.ds-home-exchange{background:#d9e7dc;color:#254337;border-radius:12px;padding:28px;margin-top:32px}.ds-home-exchange h2{font:400 2rem/1.35 var(--shop-display,Anton,sans-serif)}.ds-home-exchange a{color:#254337}@media(max-width:850px){.ds-home{padding:0 24px 40px}.ds-home-budgets{grid-template-columns:1fr}}@media(max-width:600px){.ds-home{padding:0 16px 32px}.ds-home-panel,.ds-home-exchange{padding:20px 16px}.ds-home-panel h2{font-size:1.25rem}.ds-home-budgets h2{font-size:1.75rem}}




.ds-shortcut-band {
  position: relative;
  display: flow-root;
  margin: -12px 0 28px;
}

@media(max-width:600px){.ds-shortcut-band{margin-bottom:24px}}
.ds-home-quick {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  max-width: 880px;
  gap: 32px;
  margin: 0 auto;
}
.ds-home-quick a {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
  align-items: center;
  justify-items: center;
  align-content: center;
  min-height: 144px;
  padding: 4px 12px 24px;
  border-radius: 8px;
  color: var(--shop-wine);
  font-size: 0.9375rem;
  font-weight: 700;
  text-align: center;
  text-decoration: none;
}
.ds-bookmark-backing {
  position: absolute;
  inset: 0;
  z-index: -2;
  width: 100%;
  height: 100%;
  pointer-events: none;
  fill: var(--shop-wine);
  transform: translate(2px, 3px);
}
.ds-bookmark-paper {
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  pointer-events: none;
  fill: var(--bookmark-ground, #fffaf0);
  stroke: #c5ad8f80;
  stroke-width: 1px;
  transform-origin: 50% 85%;
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1), filter 180ms ease-out;
}
.ds-bookmark-texture {
  opacity: 0.2;
  mix-blend-mode: multiply;
}
.ds-bookmark-thread {
  fill: none;
  stroke: var(--shop-wine);
  stroke-linecap: round;
  stroke-dasharray: 2px 5px;
  opacity: 0.35;
}
.ds-home-quick a > img {
  width: 88px;
  height: 88px;
  object-fit: contain;
  transform: translateY(-2px);
  transform-origin: 50% 75%;
}
.ds-home-quick a > span {
  min-width: 0;
  overflow-wrap: anywhere;
  line-height: 1.6;
}
.ds-home-quick a > img,
.ds-home-quick a > span {
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-quick-buy,
.ds-quick-auction {
  --bookmark-ground: #f6e0a8;
}
.ds-quick-exchange {
  --bookmark-ground: #fffaf0;
}
.ds-quick-post {
  --bookmark-ground: #fffaf0;
}
.ds-home-quick a:focus-visible {
  outline: 3px solid var(--shop-wine);
  outline-offset: 3px;
}
@media (hover: hover) and (pointer: fine) {
  .ds-home-quick a:hover .ds-bookmark-paper {
    transform: translateY(-5px) rotate(-1deg);
    filter: drop-shadow(0 9px 10px #28191426);
  }
  .ds-home-quick a:hover > span {
    transform: translateY(-5px);
  }
  .ds-home-quick a:hover > img {
    transform: translateY(-8px) rotate(-5deg) scale(1.08);
  }
  .ds-home-quick a:hover .ds-bookmark-paper,
  .ds-home-quick a:hover > img,
  .ds-home-quick a:hover > span {
    transition-duration: 280ms;
  }
  .ds-home-quick a:hover {
    --bookmark-motion-duration: 280ms;
  }
}
.ds-home-quick a:focus-visible .ds-bookmark-paper {
  transform: translateY(-5px) rotate(-1deg);
  filter: drop-shadow(0 9px 10px #28191426);
}
.ds-home-quick a:focus-visible > span {
  transform: translateY(-5px);
}
.ds-home-quick a:focus-visible > img {
  transform: translateY(-8px) rotate(-5deg) scale(1.08);
}
.ds-home-quick a:focus-visible {
  --bookmark-motion-duration: 280ms;
}
.ds-home-quick a:is(:hover, :focus-visible) {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.ds-home-quick a:active .ds-bookmark-paper {
  transform: translate(1px, 1px);
  filter: drop-shadow(0 2px 3px #28191414);
}
.ds-home-quick a:active > span {
  transform: translateY(1px);
}
.ds-home-quick a:active > img {
  transform: translateY(-1px) scale(0.98);
}
.ds-home-quick a:active .ds-bookmark-paper,
.ds-home-quick a:active > img,
.ds-home-quick a:active > span {
  transition-duration: 100ms;
}
.ds-home-quick a:active {
  --bookmark-motion-duration: 100ms;
}
/* Owner requests visible motion even with OS reduction enabled; interaction only. */
@media (prefers-reduced-motion: reduce) {
  .ds-bookmark-paper,
  .ds-home-quick a > img,
  .ds-home-quick a > span {
    transition-duration: var(--bookmark-motion-duration, 180ms) !important;
  }
}

@media(max-width:1000px){.ds-home-quick{grid-template-columns:repeat(2,minmax(0,1fr));max-width:440px;gap:16px}}@media(max-width:600px){.ds-home-quick{gap:12px}.ds-home-quick a{font-size:.875rem;padding:4px 10px 28px;min-height:152px}.ds-home-quick a>img{width:88px;height:88px}}
