.ds-autumn-ornaments {
  --ornament-edge: clamp(4px, calc((100% - 1200px) / 4), 54px);
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}
.ds-autumn-motif {
  --motif-size: 48px;
  --motif-angle: 0deg;
  position: absolute;
  left: var(--ornament-edge);
  width: var(--motif-size);
  height: var(--motif-size);
  background-image: url("/illustrations/autumn/motifs.webp");
  background-size: 300% 200%;
  background-repeat: no-repeat;
  opacity: 0.3;
  transform: rotate(var(--motif-angle));
}
.ds-autumn-motif:nth-child(even) {
  left: auto;
  right: var(--ornament-edge);
}
.ds-autumn-maple {
  background-position: 0% 0%;
}
.ds-autumn-oval {
