.ds-autumn-canopies {
  position: absolute;
  inset: 0 0 auto;
  height: clamp(240px, 32vw, 400px);
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}
.ds-canopy-left,
.ds-canopy-right {
  position: absolute;
  top: 0;
  width: clamp(220px, 26vw, 400px);
  aspect-ratio: 3 / 4;
  background-image: url("/illustrations/autumn/canopies.webp");
  background-size: 200% 100%;
  background-repeat: no-repeat;
}
.ds-canopy-left {
  left: 0;
  background-position: left top;
}
.ds-canopy-right {
  right: 0;
  background-position: right top;
}

@media(max-width:600px){.ds-autumn-canopies{height:180px}.ds-canopy-left,.ds-canopy-right{width:145px}}
.ds-home>.ds-autumn-canopies{position:absolute;z-index:0}









.ds-home-post{display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 32px;
  position: relative;
  z-index: 1;
  width: calc(100% - 260px);
  padding: 32px 96px 32px 36px;
  background: var(--shop-wine);
  color: var(--shop-cream);
  border-radius: 12px;
  margin: 0;}
.ds-home-post h2{font: 400 clamp(2rem, 3vw, 2.5rem)/1.35 var(--shop-display);
  margin: 0 0 16px;}
.ds-home-post h2 span{color: var(--shop-yellow);}
.ds-home-post p{font-size: 0.875rem;
  line-height: 1.8;
  margin: 0;}
.ds-home-post-action{flex-shrink: 0;}
.ds-home-post a{display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  padding: 12px 24px;
  min-height: 48px;
  border-radius: 8px;
  color: var(--shop-wine);
  background: var(--shop-cream);
  font-weight: 700;
  text-decoration: none;}
.ds-home-post a:hover{background: var(--shop-yellow);}
.ds-home-post-action p{text-align: center;
  font-size: 0.8125rem;
  margin-top: 12px;}
.ds-home-post :focus-visible{outline-color: var(--shop-cream);}
.ds-autumn-closing{position: relative;
  isolation: isolate;
  z-index: 1;
  margin: 32px -40px -56px;
  padding: 72px 40px 100px;
  overflow: hidden;
  background: #ffefcb;}
.ds-closing-landscape{position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  mask-image: linear-gradient(to bottom, transparent, #000 72px);}
.ds-closing-landscape img{position: absolute;
  bottom: 0;
  left: 50%;
  width: 100%;
  min-width: 960px;
  max-width: none;
  height: auto;
  transform: translateX(-50%);
  user-select: none;}
.ds-closing-inner{position: relative;
  max-width: 1200px;
  margin-inline: auto;}
.ds-closing-fox{position: absolute;
  z-index: 2;
  right: 0;
  bottom: -100px;
  width: 340px;
  height: 380px;
  object-fit: contain;
  object-position: center bottom;
  pointer-events: none;
  user-select: none;}
@media (max-width: 1100px){.ds-home-post{width: calc(100% - 210px);
    flex-wrap: wrap;}
.ds-closing-fox{width: 290px;
    height: 350px;}
}
@media (max-width: 850px){.ds-autumn-closing{margin-inline: -24px;
    margin-bottom: -40px;
    padding: 40px 24px 24px;}
.ds-home-post{display: block;
    width: 100%;
    padding: 28px 24px 48px;}
.ds-closing-inner{padding-bottom: 200px;}
.ds-closing-fox{width: 220px;
    height: 240px;
    bottom: -24px;}
.ds-home-post-action{width: 100%;
    margin-top: 20px;}
}
@media (max-width: 600px){.ds-autumn-closing{margin: 24px -16px -32px;
    padding-inline: 16px;}
.ds-home-post{padding: 28px 24px 48px;}
.ds-home-post-action{width: 100%;}
.ds-home-post h2{font-size: 2rem;}
}

/* Home motion: static sample; runtime observers/WAAPI are described above. */
.ds-home-categories button,.ds-home-filters button{transition:background-color 150ms ease-out,color 150ms ease-out,border-color 150ms ease-out,transform 120ms cubic-bezier(.16,1,.3,1)}
.ds-home-categories button:active,.ds-home-filters button:active{transform:translateY(1px) scale(.98)}
.ds-home-post a{transition:background-color 160ms ease-out,transform 120ms cubic-bezier(.16,1,.3,1)}
.ds-home-post a:active{transform:translateY(1px) scale(.98)}
@media(prefers-reduced-motion:reduce){.ds-home-categories button,.ds-home-filters button,.ds-home-post a{transition-duration:150ms!important}}
